        expected = audio_math_fft_factors_11;
        count = sizeof audio_math_fft_factors_11;
        break;
    case 15:
        order = audio_math_fft_permutation_15;
        expected = audio_math_fft_factors_15;
        count = sizeof audio_math_fft_factors_15;
        break;
    case 16:
        order = audio_math_fft_permutation_16;
        expected = audio_math_fft_factors_16;
        count = sizeof audio_math_fft_factors_16;
        break;
    case 20:
