    for (size_t pair = 0; pair < count / (2 * sizeof *expected); ++pair) {
        size_t index = 2 * pair;
        if (factors[index] != expected[index] || factors[index + 1] != expected[index + 1])
            return NULL;
        if (factors[index + 1] == 1)
            return order;
    }
    return NULL;
